INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Bedrohungsmodellierung nur für neue Systeme nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch bestehende Systeme profitieren"}, {"text": "Ja", "correct": false, "because": "Bedrohungen entwickeln sich weiter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Bedrohungsmodellierung?', 3, '[{"text": "Identifikation von Angriffsvektoren", "correct": true, "because": "Zeigt Schwachstellen auf"}, {"text": "Performance-Steigerung", "correct": false, "because": "Nicht primär relevant"}, {"text": "Kostensenkung", "correct": false, "because": "Sicherheit steht im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum STRIDE-Modell?', 5, '[{"text": "Spoofing", "correct": true, "because": "Täuscht Identitäten"}, {"text": "Tampering", "correct": true, "because": "Verändert Daten"}, {"text": "Rendering", "correct": false, "because": "Kein Bedrohungsaspekt"}, {"text": "Speed", "correct": false, "because": "Keine Sicherheitskategorie"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) STRIDE hilft bei Bedrohungsanalyse. b) Es ist nur für Hardware relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "STRIDE gilt für Software und Systeme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Bedrohungsmodellierung?', 4, '[{"text": "Potenzielle Angriffspunkte", "correct": false, "because": "Kern der Analyse"}, {"text": "Systemkomponenten", "correct": false, "because": "Müssen untersucht werden"}, {"text": "Farbschema", "correct": true, "because": "Nicht sicherheitsrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Bedrohungsmodellierung auch präventiv wirkt?', 2, '[{"text": "Ja", "correct": true, "because": "Verhindert Schwachstellen frühzeitig"}, {"text": "Nein", "correct": false, "because": "Proaktive Maßnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Modell nutze ich für eine umfassende Bedrohungsanalyse?', 3, '[{"text": "STRIDE", "correct": true, "because": "Deckt viele Bedrohungstypen ab"}, {"text": "Waterfall", "correct": false, "because": "Entwicklungsmethodik"}, {"text": "Agile", "correct": false, "because": "Projektmanagement"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Bedrohungsmodellierung?', 5, '[{"text": "Systemabbildung", "correct": true, "because": "Identifiziert Komponenten"}, {"text": "Bedrohungen kategorisieren", "correct": true, "because": "Nutzt z. B. STRIDE"}, {"text": "Farbanpassung", "correct": false, "because": "Nicht relevant"}, {"text": "Code-Optimierung", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Bedrohungsmodellierung findet Risiken. b) Sie behebt sie direkt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Behebung ist separater Schritt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Bedrohungsmodellierung?', 4, '[{"text": "Systemübersicht", "correct": false, "because": "Grundlage der Analyse"}, {"text": "Bedrohungskategorien", "correct": false, "because": "Strukturiert die Untersuchung"}, {"text": "Typografische Regeln", "correct": true, "because": "Nicht sicherheitsrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist STRIDE nur für Softwareentwicklung?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Netzwerke und Systeme"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bedrohungen deckt STRIDE ab?', 4, '[{"text": "Elevation of Privilege", "correct": true, "because": "Unerlaubte Rechte"}, {"text": "Denial of Service", "correct": true, "because": "Verfügbarkeitsangriff"}, {"text": "Data Loss", "correct": false, "because": "Folge, kein STRIDE-Element"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Bedrohungsmodellierung zu komplex ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann schrittweise erfolgen"}, {"text": "Ja", "correct": false, "because": "Mit Modellen wie STRIDE machbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Bedrohungsmodellierung?', 3, '[{"text": "Kritische Komponenten", "correct": true, "because": "Höchstes Risiko"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Nicht relevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Gründlichkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bedrohungsmodellierung braucht Datenfluss. b) Sie ist nur für große Firmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenfluss zeigt Angriffspunkte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools unterstützen Bedrohungsmodellierung?', 5, '[{"text": "Microsoft Threat Modeling Tool", "correct": true, "because": "Nutzt STRIDE"}, {"text": "OWASP Threat Dragon", "correct": true, "because": "Open-Source-Lösung"}, {"text": "Photoshop", "correct": false, "because": "Für Design, nicht Sicherheit"}, {"text": "Excel", "correct": false, "because": "Keine spezifische Unterstützung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Bedrohungsmodellierung unwichtig?', 3, '[{"text": "Datenflussanalyse", "correct": false, "because": "Zeigt Schwachstellen"}, {"text": "Bedrohungskategorien", "correct": false, "because": "Strukturiert Risiken"}, {"text": "Schriftarten", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit STRIDE? Deckt es alle Bedrohungen ab?', 3, '[{"text": "Nein", "correct": true, "because": "Fokussiert auf sechs Kategorien"}, {"text": "Ja", "correct": false, "because": "Ergänzung durch andere Modelle möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Bedrohungsmodellierung auch physische Angriffe berücksichtigt?', 2, '[{"text": "Ja", "correct": true, "because": "Abhängig vom Systemumfang"}, {"text": "Nein", "correct": false, "because": "Kann angepasst werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für eine Bedrohungsmodellierung?', 4, '[{"text": "Datenflussdiagramm", "correct": true, "because": "Visualisiert Angriffspfade"}, {"text": "Farbkodierung", "correct": false, "because": "Nicht relevant"}, {"text": "Statisches Mockup", "correct": false, "because": "Kein Sicherheitsfokus"}]');
